    Object field(Object o,String name)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
    void set(Object o,String name,Object value)throws Exception{java.lang.reflect.Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
    void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    void ui(Runnable r){runOnMainSync(r);waitForIdleSync();}
    interface Ready {boolean ready()throws Exception;}
    void await(Ready r,String reason)throws Exception{long end=SystemClock.elapsedRealtime()+4000;while(SystemClock.elapsedRealtime()<end){waitForIdleSync();if(r.ready())return;Thread.sleep(16);}throw new AssertionError(reason);}
    void event(KeyEvent event){ui(()->{if(!host.onKey(event))activity.dispatchKeyEvent(event);});}
    void key(int key){long now=SystemClock.uptimeMillis();event(new KeyEvent(now,now,0,key,0));event(new KeyEvent(now,now+30,1,key,0));}
    void hold(int key,boolean repeats){long now=SystemClock.uptimeMillis();event(new KeyEvent(now,now,0,key,0));if(repeats)event(new KeyEvent(now,now+TvRemotePress.HOLD_MS,0,key,1));event(new KeyEvent(now,now+TvRemotePress.HOLD_MS+10,1,key,0));}
